// Renders the shared component fixtures through the CLI's embed envelope,
// once per color scheme, into public/embeds/, where the docs component
// pages frame them as live, interactive examples. Like the demo render,
// the outputs are uncommitted build artifacts regenerated by the docs
// dev and build scripts, so the embeds always match the local renderer.
import { execFileSync } from "node:child_process";
import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import {
  ANNOTATION_FIXTURE,
  CALLOUTS_FIXTURE,
  DIFF_FIXTURE,
  FILE_TREE_FIXTURE,
  SNIPPET_FIXTURE,
  TREE_DIFF_FIXTURE,
} from "./component-fixtures.mjs";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..", "..");
const OUT_DIR = join(ROOT, "docs", "public", "embeds");
const CLI = join(ROOT, "bin", "big-plan.mjs");

const EMBEDS = [
  { name: "callout-types", mdx: CALLOUTS_FIXTURE },
  { name: "code-diff", mdx: DIFF_FIXTURE },
  { name: "code-diff-annotated", mdx: ANNOTATION_FIXTURE },
  { name: "code-snippet-annotated", mdx: SNIPPET_FIXTURE },
  { name: "file-tree-plain", mdx: FILE_TREE_FIXTURE },
  { name: "file-tree-diff", mdx: TREE_DIFF_FIXTURE },
];

const dir = mkdtempSync(join(tmpdir(), "big-plan-embeds-"));
mkdirSync(OUT_DIR, { recursive: true });
try {
  for (const { name, mdx } of EMBEDS) {
    const input = join(dir, `${name}.mdx`);
    writeFileSync(input, mdx);
    for (const theme of ["light", "dark"]) {
      const output = join(OUT_DIR, `${name}-${theme}.html`);
      execFileSync(process.execPath, [
        CLI,
        "render",
        input,
        output,
        "--embed",
        "--theme",
        theme,
      ]);
      console.log(`generated embeds/${name}-${theme}.html`);
    }
  }
} finally {
  rmSync(dir, { recursive: true, force: true });
}
